import {
    Record,
    IntegerColumn,
    StringColumn,
    ScriptColumn,
    DocumentIdColumn,
    ReferenceColumn,
    TableNameColumn,
    BooleanColumn,
    type Schema,
    Table,
} from '../../db'
import { Test } from 'ts-toolbelt'

Table({
    schema: {
        // @ts-expect-error String is not a column
        one: 'wrong',
    },
})

const intcol = IntegerColumn({
    choices: {
        1: 'one',
        '2': 'two',
        '3': 'three',
    },
    dropdown: 'dropdown_with_none',
    default: 1,
})

IntegerColumn({
    choices: {
        1: 'one',
        '2': 'two',
        '3': 'three',
    },
    dropdown: 'dropdown_with_none',
    default: '4',
})

const intcol2 = IntegerColumn({
    choices: {
        1: 'one',
        2: 'two',
        3: 'string',
        4: 'column',
    },
    dropdown: 'dropdown_with_none',
})

const strcol4 = StringColumn({
    choices: {
        '1': 'one',
        two: 'two',
    },
})

const TestTableSchema = Table({
    name: 't',
    schema: {
        1: intcol,
        2: strcol4,
        3: intcol2,
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface TestTable extends Helper<typeof TestTableSchema> {}
            }

            interface Tables {
                t: Table<TableSchemas.TestTable>
            }
        }
    }
}

Record({
    table: 't',
    $id: 0,
    data: {
        1: 1,
        '2': 'two',
        // @ts-expect-error Value of 5 for column 3 is not valid (choices are 1, 2, 3, or 4)
        3: 5,
    },
})

const col3 = StringColumn({
    choices: {
        c1: 'choice1',
        c2: {
            label: 'label',
        },
    },
})

const col = StringColumn({
    choices: {
        choice1: {
            dependent_value: '5',
            inactive_on_update: true,
            label: 'label1',
        },
        choice2: {
            inactive_on_update: true,
            label: 'label2',
            sequence: 1,
        },
        choice3: {
            label: 'label',
        },
    },
    default: 'choice1',
})

const col2 = StringColumn({ default: '1' })

const NameTableSchema = Table({
    name: 'name_table',
    schema: {
        col: col,
        col2: col2,
        col3: col3,
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface NameTable extends Helper<typeof NameTableSchema> {}
            }

            interface Tables {
                name_table: Table<TableSchemas.NameTable>
            }
        }
    }
}

const nameTableRecord = Record({
    table: 'name_table',
    $id: 1,
    data: {
        col: 'choice1',
    },
})

const RefTableSchema = Table({
    name: 'ref_table',
    schema: {
        col: ReferenceColumn({
            label: 'RefLabel',
            referenceTable: 'name_table',
            mandatory: true,
            readonly: false,
        }),
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface RefTable extends Helper<typeof RefTableSchema> {}
            }

            interface Tables {
                ref_table: Table<TableSchemas.RefTable>
            }
        }
    }
}

Record({
    table: 'ref_table',
    $id: 2,
    data: {
        col: nameTableRecord,
    },
})

const MyTableSchema = Table({
    name: 'some_table',
    schema: {
        col: IntegerColumn({
            choices: {
                one: 'Choice One',
                3: 'Choice Three',
            },
            default: 3,
        }),
    },
})

const OtherTableSchema = Table({
    name: 'other_table',
    schema: {
        ref: ReferenceColumn({ referenceTable: 'name_table' }),
        ref2: ReferenceColumn({ referenceTable: 'some_table' }),
        str: StringColumn({}),
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface MyTable3 extends Helper<typeof MyTableSchema> {}
                interface OtherTable extends Helper<typeof OtherTableSchema> {}
            }

            interface Tables {
                some_table: Table<TableSchemas.MyTable3>
                other_table: Table<TableSchemas.OtherTable>
            }
        }
    }
}

const otherTableRecord = Record({
    table: 'name_table',
    $id: 3,
    data: {
        col: 'choice1',
    },
})

Record({
    table: 'other_table',
    $id: 4,
    data: {
        ref: otherTableRecord,
        // @ts-expect-error Referencing a record on the wrong table
        ref2: otherTableRecord,
    },
})

Table({
    name: 'some_table',
    schema: {
        col: IntegerColumn({ choices: { 1: 'Choice One', 2: 'Choice Two' }, default: 1 }),
    },
})

Table({
    name: 'foo',
    schema: {
        col1: TableNameColumn({ label: 'label' }),
        col2: DocumentIdColumn({ dependent: 'col1' }),
        col3: ScriptColumn({}),
    },
})

Record({
    table: 'sys_app_application',
    $id: 6,
    data: {
        name: 'test1',
        title: 'test1',
        sys_update_name: 'test_name',
    },
})

Record({
    table: 'sys_package',
    $id: 7,
    data: {
        version: '123.345.456', // Valid
    },
})

Record({
    table: 'sys_package',
    $id: 8,
    data: {
        // @ts-expect-error Invalid version string
        version: '1.0',
    },
})

Record({
    table: 'sys_package',
    $id: 9,
    data: {
        // @ts-expect-error Invalid version string
        version: '1.0.0.0',
    },
})

Record({
    table: 'sys_package',
    $id: 10,
    data: {
        // @ts-expect-error Invalid version string
        version: 'abc',
    },
})

type XOtherSchema = (typeof XOtherSchema)['schema']
const XOtherSchema = Table({
    name: 'x_other',
    schema: {
        active: BooleanColumn({}),
    },
})

type XExampleSchema = (typeof XExampleSchema)['schema']
const XExampleSchema = Table({
    name: 'x_example',
    schema: {
        name: StringColumn({}),
        other: ReferenceColumn({
            referenceTable: 'x_other',
        }),
        state: IntegerColumn({
            choices: {
                0: 'Open',
                1: 'Closed',
            },
        }),
    },
})

declare global {
    namespace Now {
        namespace Internal {
            namespace TableSchemas {
                interface XOther extends XOtherSchema {}
                interface XExample extends XExampleSchema {}
            }

            interface Tables {
                x_other: Table<TableSchemas.XOther>
                x_example: Table<TableSchemas.XExample>
            }
        }
    }
}

Test.checks([Test.check<keyof Schema<'x_example'>, 'name' | 'other' | 'state', Test.Pass>()])
